using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
[InitializeOnLoad]public static class CityTaxiVBuild{static CityTaxiVBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityTaxiV.request"))return;var mode=File.ReadAllText("CityTaxiV.request").Trim();File.Delete("CityTaxiV.request");try{if(mode=="build")Build();else Audit();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/TaxiV.txt",e.ToString());Debug.LogException(e);}}
static void Audit(){var s=SceneManager.GetActiveScene();var r=s.GetRootGameObjects().Single(x=>x.name=="Taxi Stand - Corner 39");foreach(var renderer in r.GetComponentsInChildren<Renderer>(true)){Debug.Log("TAXIV_RENDER "+renderer.name+" enabled="+renderer.enabled+" bounds="+renderer.bounds+" localMesh="+renderer.GetComponent<MeshFilter>().sharedMesh.bounds);}var b=new StringBuilder("SCENE="+s.path+"\nROOT "+r.transform.position+" ROT "+r.transform.eulerAngles+" SCALE "+r.transform.lossyScale+"\n");foreach(var x in s.GetRootGameObjects().SelectMany(t=>t.GetComponentsInChildren<Renderer>(true)).Where(x=>x.gameObject.activeInHierarchy&&!x.transform.IsChildOf(r.transform)&&Vector3.Distance(x.bounds.center,r.transform.position)<35).OrderBy(x=>Vector3.Distance(x.bounds.center,r.transform.position)).Take(28)){var p=r.transform.InverseTransformPoint(x.bounds.center);b.AppendLine(x.name+" centerLocal="+p+" size="+x.bounds.size+" world="+x.bounds.center);}File.WriteAllText("FinalEnvironmentRoadReview/TaxiV.txt",b.ToString());}static void Box(GameObject root,Vector3 p,Vector3 size,Quaternion rotation){var go=new GameObject("Static collision");go.transform.SetParent(root.transform,false);go.transform.localPosition=p;go.transform.localRotation=rotation;go.AddComponent<BoxCollider>().size=size;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);}
static void Build(){var sc=SceneManager.GetActiveScene();var current=sc.GetRootGameObjects().Single(x=>x.name=="Taxi Stand - Corner 39");const string dir="Assets/Scenes/Oasis/TaxiStand";const string backup="FinalEnvironmentRoadBackup/BeforeTaxiOpenV";Directory.CreateDirectory(backup);if(!File.Exists(backup+"/Scene.unity"))UnityEditor.SceneManagement.EditorSceneManager.SaveScene(sc,backup+"/Scene.unity",true);var near=StackHouse3DSigns.BuildTaxiV(true);var far=StackHouse3DSigns.BuildTaxiV(false);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Shared material shader errors");GameObject root;bool rebuilding=current.GetComponentsInChildren<MeshFilter>(true).Any(x=>x.sharedMesh&&x.sharedMesh.name.StartsWith("Taxi Open V"));if(rebuilding){root=current;if(PrefabUtility.IsPartOfPrefabInstance(root))PrefabUtility.UnpackPrefabInstance(root,PrefabUnpackMode.OutermostRoot,InteractionMode.AutomatedAction);foreach(var child in root.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);foreach(var c in root.GetComponents<Collider>())UnityEngine.Object.DestroyImmediate(c);var oldLod=root.GetComponent<LODGroup>();if(oldLod)UnityEngine.Object.DestroyImmediate(oldLod);}else{root=new GameObject("Taxi Stand - Corner 39");root.transform.SetPositionAndRotation(current.transform.position,current.transform.rotation);root.transform.localScale=current.transform.localScale;current.name="Taxi Stand - Previous Four Bay Layout (inactive)";current.SetActive(false);}
var nr=new System.Collections.Generic.List<Renderer>();var fr=new System.Collections.Generic.List<Renderer>();int nt=0,ft=0;for(int i=0;i<near.Length;i++)foreach(bool full in new[]{true,false}){var m=full?near[i]:far[i];var path=dir+"/"+m.name+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){saved.Clear();saved.indexFormat=m.indexFormat;saved.vertices=m.vertices;saved.normals=m.normals;saved.uv=m.uv;var marks=new System.Collections.Generic.List<Vector4>();m.GetUVs(3,marks);saved.SetUVs(3,marks);saved.triangles=m.triangles;saved.RecalculateBounds();EditorUtility.SetDirty(saved);UnityEngine.Object.DestroyImmediate(m);m=saved;}else AssetDatabase.CreateAsset(m,path);var go=new GameObject(m.name);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=m;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.allowOcclusionWhenDynamic=false;r.shadowCastingMode=i==3?UnityEngine.Rendering.ShadowCastingMode.Off:UnityEngine.Rendering.ShadowCastingMode.On;GameObjectUtility.SetStaticEditorFlags(go,0);if(full){nr.Add(r);nt+=m.triangles.Length/3;}else{fr.Add(r);ft+=m.triangles.Length/3;}}
var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.12f,nr.ToArray()),new LOD(.003f,fr.ToArray())});lod.RecalculateBounds();foreach(var data in new[]{new[]{new Vector3(-1,0,-6.5f),new Vector3(12,0,-6),new Vector3(-.0384f,0,.9993f)},new[]{new Vector3(-1,0,-6.5f),new Vector3(-12,0,0),new Vector3(.5087f,0,.8609f)}}){var center=(data[0]+data[1])*.5f;var q=Quaternion.LookRotation(data[2]);float length=Vector3.Distance(data[0],data[1]);Box(root,center+q*new Vector3(0,5.72f,2.25f),new Vector3(length+.65f,.5f,6),q);foreach(float x in new[]{data[1].x>0?length*.5f-.22f:-length*.5f+.22f})foreach(float z in new[]{-.22f,4.95f})Box(root,center+q*new Vector3(x,2.68f,z),new Vector3(.22f,5.36f,.22f),q);}
foreach(float x in new[]{-3.8f,-.4f})Box(root,new Vector3(x,2.68f,-7),new Vector3(.22f,5.36f,.22f),Quaternion.identity);
Box(root,new Vector3(-1.8f,1.55f,-4.9f),new Vector3(3.2f,3.1f,3.6f),Quaternion.identity);Box(root,new Vector3(12,.13f,3.1f),new Vector3(1.4f,.26f,2.6f),Quaternion.identity);GameObjectUtility.SetStaticEditorFlags(root,StaticEditorFlags.OccludeeStatic);PrefabUtility.SaveAsPrefabAssetAndConnect(root,dir+"/Taxi Stand - Open V Five Bays.prefab",InteractionMode.AutomatedAction);
var control=sc.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=control&&control.IsNight;var capture=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);try{if(control)control.Apply(false);capture.Invoke(null,new object[]{sc,root.transform.TransformPoint(new Vector3(4,9,28)),root.transform.TransformPoint(new Vector3(0,2,-1)),"TaxiV-Day"});capture.Invoke(null,new object[]{sc,root.transform.TransformPoint(new Vector3(0,39,.01f)),root.transform.TransformPoint(new Vector3(0,0,0)),"TaxiV-Top"});foreach(var r in nr.Concat(fr).Where(r=>r.name.Contains("Canopy")))r.enabled=false;try{capture.Invoke(null,new object[]{sc,root.transform.TransformPoint(new Vector3(0,39,.01f)),root.transform.TransformPoint(new Vector3(0,0,0)),"TaxiV-Layout"});}finally{foreach(var r in nr.Concat(fr).Where(r=>r.name.Contains("Canopy")))r.enabled=true;}if(control)control.Apply(true);capture.Invoke(null,new object[]{sc,root.transform.TransformPoint(new Vector3(4,9,28)),root.transform.TransformPoint(new Vector3(0,2,-1)),"TaxiV-Night"});}finally{if(control)control.Apply(night);}
if(root.GetComponentsInChildren<Renderer>(true).SelectMany(x=>x.sharedMaterials).Distinct().Count()!=1||root.GetComponentsInChildren<Light>(true).Length!=0)throw new Exception("Shared material or realtime-light validation failed");AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(sc);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/TaxiV.txt","SUCCESS: Double-sided canopy signs, separated lettering/backing, inner front posts relocated behind booth with matching colliders. Open splayed V layout with 3+2 numbered bays (01-05), blue/silver canopies and cyan edge strips, booth at rear joint, separate taxi-pylon island, clear central turning court and front entrance. Reuses original material/atlas; no new materials/textures/lights. Original four-bay layout kept inactive for recovery. Near triangles="+nt+" far="+ft+"; four renderers per LOD. Shader errors=0.\nPrefab="+dir+"/Taxi Stand - Open V Five Bays.prefab");}
}






